// Per-size content for the "compress to X KB" landing pages, so each page
// gives advice that is actually specific to its size instead of a template.
// Measured results come from sizeTests.ts (generated by running the real tool).

export interface SizeFaq {
  question: string;
  answer: string;
}

export interface SizeContent {
  metaDescription: string; // keep under ~150 characters
  bestFor: string; // one line shown under the H1
  expect: string; // what realistically fits at this size
  tips: string[]; // size-specific tips
  faqs: SizeFaq[]; // size-specific questions
}

